PayloadDto PayloadDto::fromJson(const json &j) {
  PayloadDto payloadDto;
  payloadDto.hash = StringUtils::getStringOr(j, "hash");
  payloadDto.version = StringUtils::getStringOr(j, "version");
  payloadDto.objectType = StringUtils::getStringOr(j, "objectType");
  payloadDto.objectName = StringUtils::getStringOr(j, "objectName");
  payloadDto.compressionType = StringUtils::getStringOr(j, "compressionType");
  payloadDto.checkSum = StringUtils::getStringOr(j, "checkSum");
  payloadDto.size(j.value("size", std::size_t{0}));
  if (j.contains(std::string{"insertionTime"}))
    payloadDto.insertionTime = j.value("insertionTime", "");
  return payloadDto;
}
